import type { ComponentType } from 'react'
// @ts-expect-error virtual module generated by article-meta plugin
import articleMetaData from 'virtual:article-meta'

export interface ArticleMeta {
  slug: string
  title: string
  date: string
  description?: string
  tags?: string[]
  category?: string
  readingTime?: number
  wordCount?: number
}

export interface Article extends ArticleMeta {
  Component: ArticleComponent
}

export type ArticleComponent = ComponentType<{
  components?: Record<string, ComponentType<unknown>>
}>

type MdxModule = {
  default: ArticleComponent
}

// Metadata from virtual module — generated by Vite plugin at build time from filesystem
// No MDX compilation, no heavy deps
const articlesMeta: ArticleMeta[] = (articleMetaData as ArticleMeta[]).sort((a, b) => {
  if (!a.date && !b.date) return 0
  if (!a.date) return 1
  if (!b.date) return -1
  return new Date(b.date).getTime() - new Date(a.date).getTime()
})

// Lazy import for article components — each article gets its own chunk
const mdxLoaders = import.meta.glob<MdxModule>('../content/**/*.mdx')

export async function getArticles(): Promise<ArticleMeta[]> {
  return articlesMeta
}

export async function getArticleMeta(slug: string): Promise<ArticleMeta | undefined> {
  return articlesMeta.find(a => a.slug === slug)
}

export async function getArticleSlugs(): Promise<string[]> {
  return articlesMeta.map(a => a.slug)
}

/**
 * Get a lazy loader for the MDX component of a given slug.
 * Returns a function suitable for React.lazy().
 */
export function getArticleImporter(
  slug: string,
): (() => Promise<MdxModule>) | undefined {
  const filepath = `../content/${slug}.mdx`
  return mdxLoaders[filepath]
}

export function tagList(articles: ArticleMeta[]): string[] {
  const tags = new Set<string>()
  articles.forEach(a => a.tags?.forEach(t => tags.add(t)))
  return [...tags].sort()
}

export function formatDate(dateString: string): string {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
  })
}
